    INSERT INTO dbo.[Users] ([Id], [Username], [PasswordHash], [FirstName], [LastName], [Email], [Phone], [City], [Ward], [Address], [Avatar], [CreatedAt], [Role], [Status], [AuthVersion]) VALUES (28, N'Táo Đỏ', N'$2y$10$IjhGJSH3s6IRkqeixy7/eOWBH6wQr2TQ2wvkxLiiUiUEHQm612o9m', N'Táo Chín', N'Màu Đỏ', N'redapple@gmail.com', N'0866070324', N'Ho Chi Minh', N'Ward Binh Dong', N'3109/4 Vuon Tao Nho', NULL, CONVERT(DATETIME2(0), N'2026-04-09T01:16:40', 126), N'user', N'active', 1);
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (1, 1, N'Vietnamese Black Coffee', N'Strong robusta coffee served over ice. Classic and bold flavor.', N'Vietnamese Black Coffee is a traditional drink made from dark-roasted Robusta coffee beans, known for its strong aroma and distinctive bitterness. When brewed using a Vietnamese phin filter, each slow-dripping drop creates a rich, pure, and refined flavor. The coffee has a deep brown color with a glossy surface, representing the authenticity of true coffee. Vietnamese people often enjoy it hot to savor the full bitterness and aroma, or iced for a refreshing experience. This beverage is perfect for those who appreciate boldness, alertness, and the authentic taste of Vietnamese coffee culture.', N'Robusta coffee beans, hot water', N'capheden.jpg', 1.50, 46.70, 127, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:04:46', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (2, 1, N'Saigon Milk Coffee', N'Traditional iced milk coffee with condensed milk.', N'Saigon Milk Coffee is a beloved Vietnamese beverage made by blending strong Robusta coffee with sweetened condensed milk. The result is a perfect balance of bitterness and sweetness, creating a rich, creamy, and smooth flavor. Traditionally brewed using a phin filter, each drop slowly drips into the layer of condensed milk, forming a beautiful contrast of dark coffee and light cream. It can be enjoyed hot for a comforting experience or served with ice for a refreshing drink. Saigon Milk Coffee captures the vibrant and dynamic spirit of Saigon in every sip.', N'Robusta coffee, sweetened condensed milk, ice', N'caphesua.jpg', 1.60, 50.00, 100, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:04:46', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (3, 1, N'Sweet Milk Coffee', N'Smooth Vietnamese blend with creamy condensed milk.', N'Sweet Milk Coffee is a smooth and creamy beverage made by combining rich, bold coffee with sweetened condensed milk. It offers a perfect harmony between the coffee’s natural bitterness and the milk’s sweetness, creating a satisfying and well-balanced flavor. The drink has a velvety texture and an inviting aroma that appeals to both coffee lovers and newcomers alike. It can be served hot for a cozy, comforting taste or over ice for a cool, refreshing treat. Sweet Milk Coffee is the perfect choice for those who enjoy a gentle sweetness with their daily cup of coffee.', N'Coffee, sweetened condensed milk, milk, ice', N'bacsiu.jpg', 1.70, 52.94, 99, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:04:46', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (4, 1, N'Salted Coffee', N'Espresso topped with lightly salted and creamy foam.', N'Salted Coffee is a unique and flavorful drink that combines the richness of strong coffee with a hint of sea salt and creamy milk. The subtle saltiness enhances the natural sweetness and aroma of the coffee, creating a perfectly balanced and smooth taste. Each sip offers a delightful contrast between salty, sweet, and bitter notes, leaving a memorable impression. It can be served hot for a cozy, comforting experience or iced for a refreshing twist. Salted Coffee is ideal for those who enjoy trying new and distinctive coffee flavors that stand out from the ordinary.', N'Coffee, milk, cream, sea salt, sugar, ice', N'caphemuoi.jpg', 2.00, 56.00, 100, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:04:46', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (5, 1, N'Cappuccino', N'Espresso with steamed milk and a smooth layer of foam.', N'Cappuccino is a classic Italian coffee beverage made with a perfect blend of espresso, steamed milk, and a thick layer of milk foam on top. It offers a rich and aromatic flavor, balancing the boldness of espresso with the creaminess of milk. The smooth foam layer adds a velvety texture and often serves as a canvas for beautiful latte art. Cappuccino is best enjoyed hot, providing a warm and comforting experience with every sip. It’s an ideal choice for coffee lovers who appreciate a harmonious mix of strength, smoothness, and elegance in their cup.', N'Espresso, steamed milk, milk foam', N'capuchino.jpg', 2.10, 65.00, 149, N'active', 1, 0, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:04:46', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (6, 1, N'Espresso', N'Rich and intense espresso shot, pure energy in a cup.', N'Espresso is a strong and concentrated coffee made by forcing hot water through finely ground coffee beans under high pressure. It has a rich, intense flavor and a thick, creamy layer of golden crema on top. Despite its small serving size, espresso delivers a bold taste and powerful aroma that form the foundation for many popular coffee drinks like cappuccino and latte. It’s best enjoyed as a quick shot to fully experience its deep, robust character. Espresso is perfect for those who appreciate pure, authentic coffee with maximum strength and flavor.', N'Finely ground coffee, hot water', N'espresso.jpg', 1.20, 66.70, 100, N'active', 1, 0, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:04:46', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (7, 1, N'Mocha', N'Chocolate-infused espresso blended with creamy milk.', N'Mocha is a delightful coffee drink that perfectly blends rich espresso, smooth steamed milk, and indulgent chocolate syrup or cocoa powder. It combines the bold taste of coffee with the sweetness of chocolate, creating a creamy and comforting flavor experience. Topped with whipped cream or a sprinkle of cocoa, mocha offers both visual appeal and a luxurious taste. It can be served hot for a cozy treat or iced for a refreshing twist. Mocha is an ideal choice for those who love the harmonious balance between coffee’s strength and chocolate’s sweetness.', N'Espresso, chocolate syrup, steamed milk, whipped cream', N'1775676167_Mocha.jpg', 2.20, 54.60, 99, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:04:46', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (8, 1, N'Caramel Macchiato', N'Espresso layered with velvety milk and caramel syrup.', N'Caramel Macchiato is a smooth and indulgent coffee drink made by layering freshly brewed espresso over steamed milk and sweet vanilla syrup, then topping it with a drizzle of golden caramel. This combination creates a beautiful balance between rich coffee flavor and creamy sweetness. The caramel adds a buttery, slightly smoky taste that enhances the overall aroma and texture. It can be enjoyed hot for a comforting experience or iced for a refreshing treat. Caramel Macchiato is perfect for those who enjoy a sweet, elegant, and well-balanced coffee beverage.', N'Espresso, steamed milk, vanilla syrup, caramel sauce', N'caramelmachiato.jpg', 3.01, 65.00, 123, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:04:46', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (9, 1, N'Coffee Cheese Foam', N'Iced coffee covered with rich and smooth cheese foam.', N'Coffee Cheese Foam is a unique and modern coffee drink that combines bold, aromatic coffee with a rich, creamy layer of cheese foam on top. The cheese foam has a slightly salty and sweet flavor, creating a perfect contrast with the bitterness of the coffee. Each sip offers a delightful mix of smooth creaminess and robust coffee taste. The drink is often served cold, allowing the foam to stay thick and velvety while blending beautifully with the chilled coffee beneath. Coffee Cheese Foam is ideal for those who enjoy creative, dessert-like coffee experiences with a luxurious twist.', N'Coffee, milk, cheese foam, sugar, ice', N'caphekemcheese.jpg', 2.15, 52.20, 121, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:04:46', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (10, 1, N'Whipped Cream Coffee', N'Iced coffee topped with thick and fluffy whipped cream.', N'Whipped Cream Coffee is a rich and indulgent beverage made by topping freshly brewed coffee with a generous layer of smooth, fluffy whipped cream. The creamy topping slowly melts into the coffee, adding sweetness and a velvety texture that perfectly balances the drink’s natural bitterness. Each sip offers a delightful blend of warm coffee and cool cream, creating a comforting and satisfying experience. It can be served hot or iced, making it enjoyable in any season. Whipped Cream Coffee is perfect for those who love a touch of luxury and sweetness in their daily cup.', N'Coffee, whipped cream, sugar, milk, ice', N'caphekemtuoi.jpg', 2.10, 57.10, 90, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:04:46', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (11, 1, N'Egg Coffee', N'Aromatic coffee crowned with silky and sweet egg foam.', N'Egg Coffee (Iced) is a luxurious Vietnamese-style coffee drink made by combining strong, aromatic coffee with a smooth, creamy foam of whipped egg yolk, milk, and sugar. The result is a rich and velvety texture with a perfect balance of sweetness and bold coffee flavor. Served over ice, it offers a refreshing twist on the traditional hot version while keeping its signature creaminess. Each sip delivers layers of flavor — the cool bitterness of coffee blending harmoniously with the sweet, custard-like foam. Iced Egg Coffee is ideal for those who enjoy unique, indulgent, and refreshing coffee experiences.', N'Coffee, egg yolk, milk, sugar, ice', N'caphekemtrung.jpg', 2.50, 52.00, 93, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:04:46', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (12, 2, N'Oolong with Lotus Seeds', N'Fragrant oolong with tender lotus seeds.', N'Oolong with Lotus Seeds is a refreshing and elegant beverage that combines the delicate aroma of oolong tea with the natural sweetness and softness of cooked lotus seeds. The floral, slightly roasted notes of oolong perfectly complement the gentle, nutty flavor of the lotus seeds, creating a soothing and balanced taste. Served chilled, it offers a calming and rejuvenating experience that’s both healthy and delicious. This drink is not only fragrant and flavorful but also rich in antioxidants and nutrients. Oolong with Lotus Seeds is perfect for those who appreciate a light, refreshing drink with an Asian-inspired touch of tradition and wellness.', N'Oolong tea, lotus seeds, sugar, water', N'traolonghatsen.png', 1.80, 61.11, 97, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:15:49', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (13, 2, N'Winter Melon & Chia', N'Lightly sweet winter melon with chia.', N'Winter Melon & Chia is a light and refreshing drink made from sweet winter melon tea blended with nutritious chia seeds. The natural sweetness of winter melon pairs perfectly with the soft, jelly-like texture of soaked chia seeds, creating a smooth and satisfying experience. Served chilled, it provides a cooling and hydrating sensation, ideal for hot days. This drink is not only delicious but also rich in fiber and antioxidants, supporting digestion and overall wellness. Winter Melon & Chia is perfect for those who enjoy a naturally sweet, healthy, and refreshing beverage.', N'Winter melon syrup, chia seeds, tea, water, ice', N'trabidaohatchia.jpg', 1.60, 62.50, 119, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:15:49', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (14, 2, N'Honey Lime Tea', N'Zesty lime balanced with honey.', N'Honey Lime Tea is a bright and refreshing drink that combines the natural sweetness of honey with the tangy zest of fresh lime. The smooth tea base enhances the balance between sweet and sour flavors, creating a light and invigorating taste. Served cold, it’s a perfect thirst-quencher on warm days, while served hot, it offers a soothing and comforting experience. This drink is rich in vitamin C and antioxidants, helping to boost energy and refresh the mind. Honey Lime Tea is ideal for those who enjoy a naturally sweet, revitalizing beverage with a citrusy twist.', N'Black tea, honey, lime juice, water, ice', N'trachanhmatong.jpg', 1.76, 63.64, 124, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:15:49', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (15, 2, N'Strawberry Tea', N'Refreshing strawberry infused tea.', N'Tea is a fragrant and refreshing drink made by blending premium tea with the sweet, fruity flavor of ripe strawberries. It offers a perfect harmony of tartness and natural sweetness, creating a vibrant and uplifting taste. Served chilled, it provides a cooling and energizing sensation, while the aroma of fresh strawberries adds a delightful touch. This drink is rich in antioxidants and vitamins, making it both delicious and nourishing. Strawberry Tea is perfect for those who love a fruity, refreshing beverage with a hint of natural elegance.', N'Black tea, strawberry syrup or puree, sugar, ice', N'tradau.jpg', 1.70, 64.71, 100, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:15:49', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (16, 2, N'Blueberry Tea', N'Bright blueberry flavors, iced.', N'Blueberry Tea is a smooth and aromatic beverage that blends high-quality tea with the sweet and slightly tangy flavor of ripe blueberries. It delivers a refreshing balance between fruitiness and the gentle bitterness of tea, creating a well-rounded and satisfying taste. Served cold, it offers a cool, revitalizing experience, while its vibrant color and aroma make it visually appealing. Rich in antioxidants and vitamins, this drink not only tastes great but also supports overall wellness. Blueberry Tea is perfect for those who enjoy a fruity, refreshing, and healthful tea experience.', N'Black tea, blueberry syrup or puree, sugar, ice', N'travietquat.jpg', 1.70, 64.71, 123, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:15:49', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (17, 2, N'Mango Passionfruit Tea', N'Tropical duo of mango & passionfruit.', N'Passionfruit Tea is a tropical and refreshing beverage that combines the sweetness of ripe mango with the tangy brightness of passionfruit. The smooth tea base enhances the fruity flavors, creating a perfectly balanced and invigorating taste. Each sip delivers a burst of tropical aroma and natural sweetness, making it both energizing and satisfying. Served chilled, it’s the ideal drink for hot days or anytime you crave something fruity and vibrant. Mango Passionfruit Tea is perfect for those who enjoy exotic flavors and a refreshing, sunny twist in their tea.', N'Black tea, mango syrup, passionfruit syrup, ice', N'traxoaichanhday.jpg', 2.21, 62.16, 135, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:15:49', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (18, 2, N'Tropical Fruit Tea', N'Citrus and juicy seasonal fruits.', N'Tropical Fruit Tea is a vibrant and refreshing beverage made by blending premium tea with a mix of tropical fruits such as mango, pineapple, and passionfruit. It offers a perfect balance of sweetness, tanginess, and floral aroma, capturing the essence of a tropical paradise in every sip. The tea base adds smoothness and depth, enhancing the bright fruit flavors. Served chilled, it provides a cooling and energizing experience that’s both flavorful and rejuvenating. Tropical Fruit Tea is ideal for those who love fruity, exotic drinks with a refreshing and uplifting taste.', N'Black tea, mixed tropical fruit syrup (mango, pineapple, passionfruit, ice', N'tratraicaynhietdoi.jpg', 1.90, 63.16, 100, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:15:49', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (19, 2, N'Peach Orange Lemongrass', N'Bright peach, orange and lemongrass.', N'Peach Orange Lemongrass is a refreshing and aromatic beverage that combines the sweetness of ripe peaches, the zesty brightness of oranges, and the soothing fragrance of lemongrass. The blend creates a perfectly balanced taste — fruity, citrusy, and slightly herbal. Each sip offers a smooth and uplifting flavor that energizes the senses while calming the mind. Served chilled, it’s an ideal drink for warm days, bringing both freshness and relaxation. Peach Orange Lemongrass is perfect for those who enjoy a naturally sweet, fragrant, and revitalizing tea experience.', N'Black tea, peach syrup, orange juice, lemongrass, ice', N'tradaocamsa.jpg', 1.90, 63.16, 112, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:15:49', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (20, 2, N'Pink Guava Tea', N'Fruity guava with lime.', N'Pink Guava Tea is a tropical and refreshing drink that blends fragrant tea with the sweet, slightly tangy flavor of pink guava. The combination creates a smooth and vibrant taste with a delicate fruity aroma. Each sip offers a perfect balance between the natural sweetness of guava and the gentle bitterness of tea, making it both energizing and soothing. Served cold, it delivers a cool, revitalizing sensation that’s perfect for hot days. Pink Guava Tea is ideal for those who enjoy exotic, fruity teas with a fresh and uplifting twist.', N'Black tea, pink guava syrup, sugar, ice', N'traoihong.jpg', 2.03, 62.16, 10, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:15:49', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (21, 2, N'Lychee Tea', N'Delicate lychee aroma over black tea.', N'Lychee Tea is a fragrant and refreshing beverage that combines the delicate sweetness of lychee fruit with the smooth, mellow taste of premium tea. The floral aroma and juicy flavor of lychee create a light yet flavorful drink that’s both soothing and revitalizing. Served chilled, it offers a cooling and aromatic experience that delights the senses. Each sip balances natural fruitiness with gentle tea notes, making it a perfect choice for warm days. Lychee Tea is ideal for those who enjoy a sweet, elegant, and refreshing fruit-infused tea.', N'Black tea, lychee syrup, lychee pieces, ice', N'travai.jpg', 2.10, 62.16, 91, N'active', 1, 1, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:15:49', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (22, 3, N'Chocolate Frappe', N'Creamy blended chocolate.', N'Chocolate Frappe is a rich and creamy blended beverage made with smooth chocolate, fresh milk, and ice, creating a thick and refreshing texture. It offers a perfect balance of sweetness and cocoa flavor, delivering a cool and indulgent treat in every sip. Topped with whipped cream or a drizzle of chocolate syrup, it adds an extra layer of decadence and visual appeal. This drink is both energizing and satisfying, making it ideal for chocolate lovers. Chocolate Frappe is perfect for those who crave a sweet, refreshing, and luxurious chocolate experience.', N'Chocolate syrup, milk, ice, whipped cream', N'cacaodaxay.jpg', 2.20, 70.00, 165, N'active', 1, 0, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:27:19', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (23, 3, N'Oreo Frappe', N'Cookies & cream goodness.', N'Oreo Frappe is a deliciously creamy blended drink made with crushed Oreo cookies, fresh milk, chocolate syrup, and ice for a smooth, refreshing texture. Each sip combines the sweetness of cookies and cream with the richness of chocolate, creating an irresistible dessert-like flavor. Topped with whipped cream and cookie crumbles, it’s both visually tempting and satisfyingly indulgent. Perfect for a hot day or as a sweet treat, this drink offers a delightful balance of crunch and creaminess. Oreo Frappe is ideal for those who love a fun, flavorful, and refreshing twist on classic coffeehouse favorites.', N'Oreo cookies, milk, chocolate syrup, ice, whipped cream', N'oreodaxay.jpg', 2.30, 65.22, 111, N'active', 1, 0, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:27:19', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (24, 3, N'Caramel Frappe', N'Buttery caramel blended smooth.', N'Frappe is a smooth and indulgent blended drink made with rich caramel syrup, fresh milk, espresso (optional), and ice, creating a creamy and refreshing texture. Each sip delivers a perfect mix of sweetness and coffee flavor, balanced by the buttery richness of caramel. Topped with whipped cream and a drizzle of caramel sauce, it offers both visual appeal and a luxurious taste. Served cold, it’s the perfect pick-me-up on a warm day. Caramel Frappe is ideal for those who enjoy a sweet, creamy, and energizing beverage with a touch of elegance.', N'Caramel syrup, milk, espresso (optional), ice, whipped cream', N'carameldaxay.jpg', 2.30, 65.22, 121, N'active', 1, 0, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:27:19', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (25, 3, N'Matcha Frappe', N'Premium matcha, icy & lush.', N'Matcha Frappe is a creamy and refreshing blended drink made with premium matcha green tea powder, fresh milk, and ice. It offers a smooth balance of earthy matcha flavor and natural sweetness, creating a rich yet soothing taste. The vibrant green color and velvety texture make it as visually appealing as it is delicious. Often topped with whipped cream or a sprinkle of matcha powder, it adds an extra layer of indulgence. Served cold, it’s perfect for hot days or when you need a refreshing boost. Matcha Frappe is ideal for those who enjoy a harmonious blend of flavor, energy, and elegance.', N'Matcha powder, milk, sugar, ice, whipped cream', N'matchadaxay.jpg', 2.40, 62.50, 112, N'active', 1, 0, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:27:19', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (26, 3, N'Mocha Frappe', N'Espresso & chocolate blended.', N'Mocha Frappe is a rich and refreshing blended drink that combines bold espresso, smooth milk, and indulgent chocolate syrup with ice for a perfectly creamy texture. Each sip delivers a harmonious balance of coffee strength and chocolate sweetness, making it both energizing and satisfying. Topped with whipped cream and a drizzle of chocolate sauce, it adds a touch of luxury and visual appeal. Served cold, it’s an ideal choice for warm days or when you crave a dessert-like coffee treat. Mocha Frappe is perfect for those who love the blend of coffee’s boldness and chocolate’s richness.', N'Espresso, chocolate syrup, milk, ice, whipped cream', N'socoladaxay.jpg', 2.40, 62.50, 7, N'active', 1, 0, 1, CONVERT(DATETIME2(0), N'2026-02-23T16:27:19', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (27, 4, N'Caramel Pudding', N'Silky custard with amber caramel.', N'Pudding is a smooth and creamy dessert made with a rich blend of milk, eggs, and sugar, topped with a layer of golden caramel sauce. It has a delicate, melt-in-your-mouth texture and a perfectly balanced sweetness that makes each bite irresistible. The caramel adds a subtle bitterness that enhances the pudding’s creamy flavor, creating a delightful contrast. Served chilled, it offers a comforting and refreshing treat. Caramel Pudding is perfect for those who enjoy classic desserts with a soft, silky texture and a touch of elegance.', N'Milk, eggs, sugar, caramel sauce, vanilla extract', N'pudding.jpg', 1.40, 78.60, 75, N'active', 0, 0, 0, CONVERT(DATETIME2(0), N'2026-02-23T16:30:24', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (28, 4, N'French Macarons (6 pcs)', N'Delicate almond shells, assorted.', N'Macarons are delicate and elegant sandwich cookies made with almond flour, egg whites, and sugar, filled with rich buttercream, ganache, or fruit jam. Each macaron has a smooth, crisp shell with a soft, chewy center that melts in your mouth. Available in a variety of flavors and colors — such as vanilla, chocolate, raspberry, pistachio, and lemon — they are as beautiful as they are delicious. These bite-sized treats are often enjoyed with tea or coffee, adding a touch of sophistication to any moment. French Macarons are perfect for those who appreciate refined, flavorful, and visually stunning desserts.', N'Almond flour, egg whites, sugar, buttercream or ganache filling', N'macarons.jpg', 2.60, 84.62, 88, N'active', 0, 0, 0, CONVERT(DATETIME2(0), N'2026-02-23T16:30:24', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (29, 4, N'Chocolate Mousse Cake', N'Light mousse atop cocoa sponge.', N'Chocolate Mousse Cake is a luxurious dessert made with layers of rich chocolate sponge and smooth, airy chocolate mousse. It offers a perfect balance of deep cocoa flavor and light, creamy texture, creating a melt-in-your-mouth experience. Each bite is indulgent yet delicate, with the mousse adding a silky contrast to the soft cake layers. Often topped with a glossy chocolate glaze or dusted with cocoa powder, it’s both elegant and irresistible. Served chilled, it’s a delightful treat for any occasion. Chocolate Mousse Cake is perfect for those who love decadent, smooth, and beautifully crafted desserts.', N'Chocolate, eggs, sugar, milk, cream, sponge cake base', N'mousse.jpg', 2.42, 90.91, 60, N'active', 0, 0, 0, CONVERT(DATETIME2(0), N'2026-02-23T16:30:24', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (30, 4, N'Berry Cheesecake', N'Creamy cheesecake with berries.', N'Berry Cheesecake is a rich and creamy dessert featuring a smooth cream cheese filling on a buttery biscuit crust, topped with a layer of fresh mixed berries and sweet berry glaze. The tangy flavor of the berries perfectly balances the sweetness and richness of the cheesecake, creating a refreshing and satisfying taste. Each bite offers a delightful combination of creamy, crumbly, and fruity textures. Served chilled, it’s both elegant and indulgent, making it a perfect choice for any occasion. Berry Cheesecake is ideal for those who enjoy classic desserts with a fruity, refreshing twist.', N'Cream cheese, sugar, eggs, mixed berries, biscuit crust, berry glaze', N'cheesecake.jpg', 2.40, 90.20, 5, N'active', 0, 0, 0, CONVERT(DATETIME2(0), N'2026-02-23T16:30:24', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (31, 4, N'Cream Puffs (6 pcs)', N'Choux buns filled with vanilla cream.', N'Cream Puffs are light and airy pastries made from delicate choux dough filled with smooth, sweet cream. Each puff has a crisp golden shell on the outside and a soft, creamy center that melts in your mouth. The filling can vary from classic vanilla custard to whipped cream or flavored creams like chocolate or matcha. Often dusted with powdered sugar or topped with a thin glaze, they’re as elegant as they are delicious. Served chilled or at room temperature, Cream Puffs make a perfect treat for any occasion. They’re ideal for those who love light, creamy, and irresistibly sweet pastries.', N'Flour, butter, eggs, cream filling (custard or whipped cream), sugar', N'sukem.jpg', 1.80, 100.00, 72, N'active', 0, 0, 0, CONVERT(DATETIME2(0), N'2026-02-23T16:30:24', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (32, 4, N'Butter Croissant', N'Flaky, buttery layers.', N'Butter Croissant is a classic French pastry known for its flaky, golden layers and rich buttery aroma. Made from laminated dough that’s folded and rolled multiple times, it achieves a light, airy texture with a crisp outer crust. Each bite offers a perfect balance of buttery flavor and delicate sweetness, making it irresistible at any time of day. Served warm, it pairs beautifully with coffee or tea and can be enjoyed plain or with jam. Butter Croissant is perfect for those who appreciate simple, elegant pastries with a rich, melt-in-your-mouth texture.', N'Flour, butter, sugar, yeast, milk, salt', N'croissant.jpg', 1.30, 84.62, 95, N'active', 0, 0, 0, CONVERT(DATETIME2(0), N'2026-02-23T16:30:24', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (33, 4, N'Tiramisu', N'Mascarpone, espresso & cocoa.', N'Tiramisu is a classic Italian dessert made with layers of espresso-soaked ladyfingers, creamy mascarpone cheese, and a dusting of rich cocoa powder. It offers a perfect harmony of coffee bitterness, creamy sweetness, and subtle hints of cocoa, creating a luxurious and balanced flavor. The soft, velvety texture melts in your mouth, leaving a lingering aroma of coffee and cream. Often served chilled, it’s both refreshing and indulgent. Tiramisu is perfect for those who enjoy elegant, coffee-infused desserts with a smooth and comforting taste.', N'Ladyfingers, mascarpone cheese, espresso, sugar, eggs, cocoa powder', N'tiramisu.jpg', 2.20, 90.91, 100, N'active', 0, 0, 0, CONVERT(DATETIME2(0), N'2026-02-23T16:30:24', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (34, 4, N'Yogurt with Brown Sugar Pearls', N'Tangy yogurt with chewy pearls.', N'Yogurt with Brown Sugar Pearls is a creamy and refreshing dessert drink that combines smooth, tangy yogurt with chewy brown sugar boba pearls. The rich caramel flavor of the brown sugar perfectly complements the light sourness of the yogurt, creating a balanced and satisfying taste. Each sip offers a delightful mix of textures — creamy, chewy, and slightly sweet. Served cold, it’s both energizing and comforting. Yogurt with Brown Sugar Pearls is perfect for those who enjoy a unique blend of sweetness and tanginess in a fun, refreshing treat.', N'Yogurt, brown sugar syrup, tapioca pearls, ice', N'suachuatranchau.jpg', 1.70, 76.47, 99, N'active', 0, 0, 0, CONVERT(DATETIME2(0), N'2026-02-23T16:30:24', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (35, 4, N'Blueberry Yogurt', N'Layers of yogurt and blueberry.', N'Blueberry Yogurt is a smooth and creamy beverage made by blending fresh yogurt with the sweet and tangy flavor of ripe blueberries. It offers a perfect balance between fruity sweetness and yogurt’s natural tartness, creating a refreshing and wholesome taste. Each sip is rich, velvety, and bursting with blueberry aroma. Packed with probiotics, vitamins, and antioxidants, it’s both delicious and nourishing. Served chilled, Blueberry Yogurt is perfect for those who enjoy a fruity, creamy, and healthful drink.', N'Yogurt, blueberry puree, sugar, ice', N'suachuavietquat.jpg', 1.99, 76.47, 115, N'active', 0, 0, 0, CONVERT(DATETIME2(0), N'2026-02-23T16:30:24', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (36, 4, N'Mixed Fruit Yogurt', N'Fresh fruits over creamy yogurt.', N'Mixed Fruit Yogurt is a refreshing and creamy drink made by blending smooth yogurt with a variety of fresh fruits such as mango, strawberry, blueberry, and kiwi. Each sip delivers a vibrant mix of sweet and tangy flavors, perfectly balanced by the yogurt’s natural creaminess. The combination of fruits adds both color and texture, making it as visually appealing as it is delicious. Rich in vitamins, fiber, and probiotics, it’s a healthy yet indulgent treat. Served chilled, Mixed Fruit Yogurt is perfect for those who love a fruity, refreshing, and nutritious beverage.', N'Yogurt, assorted fruits (mango, strawberry, kiwi, blueberry), sugar, ice', N'suachuatraicay.jpg', 1.80, 72.22, 80, N'active', 0, 0, 0, CONVERT(DATETIME2(0), N'2026-02-23T16:30:24', 126));
    INSERT INTO dbo.[Products] ([Id], [CategoryId], [Name], [ShortDescription], [Description], [Ingredients], [Image], [CostPrice], [ProfitPercent], [Quantity], [Status], [HasSize], [HasIce], [HasSugar], [CreatedAt]) VALUES (37, 4, N'Mango Yogurt', N'Creamy yogurt with mango.', N'A refreshing yogurt drink blended with sweet mango.', N'Yogurt, mango puree, sugar, ice', N'suachuaxoai.jpg', 1.80, 70.00, 65, N'active', 0, 0, 0, CONVERT(DATETIME2(0), N'2026-04-02T21:46:22', 126));
