-- B04 snapshot import. Source: database/metropolitan_coffee.sql (MySQL dump).
-- Source SHA-256: 99883fcb7e7ea1b236289dfc9954157a0eec5714b44c2b6d7d18d0e16d50cd90
-- Generated from the actual INSERT rows, preserving IDs, UTF-8 text, bcrypt
-- hashes, historical order prices/totals, dates, status and current stock.
-- Run ONLY on an empty schema created by 01 and 02. Skip demo script 03.
-- No destructive statements; the import rolls back on any failure.
-- B04 cart_data is [] or NULL in this snapshot, hence zero CartItems.
-- Opening stock movements capture current balances; they do not assert
-- historical purchase/sale timing or reconstruct old inventory activity.
USE [MetropolitanCoffeeDB];
GO
SET XACT_ABORT ON;
BEGIN TRY
    BEGIN TRANSACTION;
    IF EXISTS (SELECT 1 FROM dbo.Categories) OR EXISTS (SELECT 1 FROM dbo.Users)
       OR EXISTS (SELECT 1 FROM dbo.Products) OR EXISTS (SELECT 1 FROM dbo.Orders)
       OR EXISTS (SELECT 1 FROM dbo.OrderItems) OR EXISTS (SELECT 1 FROM dbo.PurchaseOrders)
       OR EXISTS (SELECT 1 FROM dbo.PurchaseOrderItems) OR EXISTS (SELECT 1 FROM dbo.CartItems)
       OR EXISTS (SELECT 1 FROM dbo.StockMovements)
        THROW 51000, 'B04 import requires all nine business tables to be empty; demo seed 03 must be skipped.', 1;

    SET IDENTITY_INSERT dbo.[Categories] ON;
    SET IDENTITY_INSERT dbo.[Categories] OFF;

    SET IDENTITY_INSERT dbo.[Users] ON;
    SET IDENTITY_INSERT dbo.[Users] OFF;

    SET IDENTITY_INSERT dbo.[Products] ON;
    SET IDENTITY_INSERT dbo.[Products] OFF;

    SET IDENTITY_INSERT dbo.[Orders] ON;
    SET IDENTITY_INSERT dbo.[Orders] OFF;

    SET IDENTITY_INSERT dbo.[OrderItems] ON;
    SET IDENTITY_INSERT dbo.[OrderItems] OFF;

    SET IDENTITY_INSERT dbo.[PurchaseOrders] ON;
    SET IDENTITY_INSERT dbo.[PurchaseOrders] OFF;

    SET IDENTITY_INSERT dbo.[PurchaseOrderItems] ON;
    SET IDENTITY_INSERT dbo.[PurchaseOrderItems] OFF;

    SELECT Id, N'opening', Quantity,
           N'B04 migration current balance; historical movements not reconstructed'
    FROM dbo.Products
    WHERE Quantity > 0;

    IF (SELECT COUNT_BIG(*) FROM dbo.[Categories]) <> 4 THROW 51001, 'Categories count mismatch', 1;
    IF (SELECT COUNT_BIG(*) FROM dbo.[Users]) <> 6 THROW 51001, 'Users count mismatch', 1;
    IF (SELECT COUNT_BIG(*) FROM dbo.[Products]) <> 37 THROW 51001, 'Products count mismatch', 1;
    IF (SELECT COUNT_BIG(*) FROM dbo.[Orders]) <> 9 THROW 51001, 'Orders count mismatch', 1;
    IF (SELECT COUNT_BIG(*) FROM dbo.[OrderItems]) <> 19 THROW 51001, 'OrderItems count mismatch', 1;
    IF (SELECT COUNT_BIG(*) FROM dbo.[PurchaseOrders]) <> 14 THROW 51001, 'PurchaseOrders count mismatch', 1;
    IF (SELECT COUNT_BIG(*) FROM dbo.[PurchaseOrderItems]) <> 48 THROW 51001, 'PurchaseOrderItems count mismatch', 1;
    IF (SELECT COUNT_BIG(*) FROM dbo.StockMovements) <> (SELECT COUNT_BIG(*) FROM dbo.Products WHERE Quantity > 0) THROW 51002, 'Opening movement count mismatch', 1;
    IF EXISTS (SELECT 1 FROM dbo.Orders o OUTER APPLY (SELECT SUM(CONVERT(DECIMAL(18,2), Price) * Quantity) AS ItemTotal FROM dbo.OrderItems i WHERE i.OrderId=o.Id) x WHERE o.Total <> ISNULL(x.ItemTotal,0)) THROW 51003, 'Historical order total mismatch', 1;
    IF EXISTS (SELECT 1 FROM dbo.Products p LEFT JOIN dbo.StockMovements sm ON sm.ProductId=p.Id GROUP BY p.Id,p.Quantity HAVING p.Quantity <> ISNULL(SUM(CONVERT(BIGINT,sm.QuantityDelta)),0)) THROW 51004, 'Opening stock mismatch', 1;

    -- Preserve the original AUTO_INCREMENT next values, including deleted-ID gaps.
    DBCC CHECKIDENT (N'dbo.Categories', RESEED, 18) WITH NO_INFOMSGS;
    DBCC CHECKIDENT (N'dbo.Users', RESEED, 28) WITH NO_INFOMSGS;
    DBCC CHECKIDENT (N'dbo.Products', RESEED, 74) WITH NO_INFOMSGS;
    DBCC CHECKIDENT (N'dbo.Orders', RESEED, 123) WITH NO_INFOMSGS;
    DBCC CHECKIDENT (N'dbo.OrderItems', RESEED, 150) WITH NO_INFOMSGS;
    DBCC CHECKIDENT (N'dbo.PurchaseOrders', RESEED, 43) WITH NO_INFOMSGS;
    DBCC CHECKIDENT (N'dbo.PurchaseOrderItems', RESEED, 80) WITH NO_INFOMSGS;
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO
